seen = set()
total = 0
meta_chapters = []
for cid, num, unit, title, qs in CH:
    rng = random.Random("e-istoria-" + cid)
    out = []
    for q in qs:
        question, right, *wrong = q
        assert len(wrong) == 3, q
        assert len(set([right] + wrong)) == 4, q
        assert question not in seen, question
        seen.add(question)
        choices = [right] + wrong
        rng.shuffle(choices)
        out.append({
            "question": question,
            "choices": [f"{i + 1}. {c}" for i, c in enumerate(choices)],
            "answer": str(choices.index(right) + 1),
        })
    total += len(out)
    with open(os.path.join(OUT, "chapters", f"{cid}.json"), "w", encoding="utf8") as f:
        json.dump(out, f, ensure_ascii=False, indent=2)
        f.write("\n")
    meta_chapters.append({"id": cid, "num": num, "title": title, "unit": unit})

meta = {
    "grade": "Ε΄ Δημοτικού",
    "source": "Σχολικό βιβλίο «Στα βυζαντινά χρόνια», Ιστορία Ε΄ Δημοτικού (ebooks.edu.gr) — ερωτήσεις από το κείμενο κάθε κεφαλαίου",
    "chapters": meta_chapters,
}
with open(os.path.join(OUT, "meta.json"), "w", encoding="utf8") as f:
    json.dump(meta, f, ensure_ascii=False, indent=2)
    f.write("\n")
print(f"{len(CH)} κεφάλαια, {total} ερωτήσεις")
